from helpers import danger, caution, tip, check, table, fig

def part6(D):
    h = ['<h1 class="part" id="p6"><small>Part 6</small>Working With Concrete by Hand</h1>']
    h.append('<h2 id="mixing">6.1 Mixing by hand</h2>')
    h.append('<div class="cols2"><div><ol>'
             '<li><b>Set up</b> on a clean, non-absorbent surface — a sheet of steel, plywood, an old car hood, a concrete pad, or a wheelbarrow/mortar box — close to where the concrete will go.</li>'
             '<li><b>Measure by volume</b> with one bucket or gauge box. Level-full, not heaped. Batch only what you can place in 60–90 minutes (less in heat).</li>'
             '<li><b>Dry-mix</b> the sand and cement, turning the pile at least 3 times until the color is completely even — no streaks.</li>'
             '<li><b>Add the gravel</b> and turn again until every stone is coated.</li>'
             '<li><b>Make a crater</b>, pour in about ¾ of the water, and fold the dry material from the edges into the middle. Turn the whole heap 3+ times, adding the rest of the water a little at a time only until the mix is just workable.</li>'
             '<li><b>Check</b>: a shovel cut should leave a clean, smooth face that holds its shape; a squeezed handful (gloved) leaves the glove wet but doesn’t drip.</li></ol></div>'
             '<div><h3>Rules of thumb</h3><ul><li>A wheelbarrow holds ~2–3 ft³ — about one bag’s worth of 1:2:3 concrete. Four people with two barrows can hand-mix and place about 1 yd³ (0.76 m³) in half a day.</li>'
             '<li>Damp sand already contains water — start with less.</li>'
             '<li>Never add water to concrete that has started to stiffen (“re-tempering”) — use it or lose it.</li>'
             '<li>Clean tools and the mixing surface immediately.</li>'
             '<li>Quantities: a 4 in (100 mm) slab 10 × 10 ft takes about 1.25 yd³ (0.95 m³): roughly 8 bags of cement, 16 ft³ of sand and 32 ft³ of gravel in 1:2:4, including ~10% for waste.</li></ul>'
             '<div class="formula"><span class="eq">yd³ = L(ft) × W(ft) × D(in) ÷ 324</span><span class="eq">m³ = L(m) × W(m) × D(m)</span>Loose dry ingredients ≈ 1.5 × finished volume.</div></div></div>')
    h.append('<h2 id="forms">6.2 Forms from salvaged lumber</h2>')
    h.append('<p>Fresh concrete weighs 150 lb/ft³ (2,400 kg/m³) and pushes on forms like a heavy liquid — about 150 lb/ft² per foot of depth at the bottom. Use 2× lumber, ¾ in plywood, old doors, sheet metal or steel drums. Stake every 2–3 ft, tie the tops together with cleats or spreaders, and brace tall forms diagonally. Seal gaps (paste leaks leave honeycombed concrete). Coat inside faces with a release agent — vegetable oil, used cooking oil, or diesel; wet bare wood before the pour. Strip side forms of footings and walls after 1–3 days; leave supports under slabs, lintels and beams 7–14+ days (longer when cold).</p>')
    h.append('<h2 id="rebar">6.3 Reinforcement in practice</h2>')
    h.append('<ul><li>Place steel before pouring and support it on <b>chairs</b> — small blocks of concrete, brick or stone — so it ends up with the correct cover (Part 2.4). Steel lying on the ground does nothing.</li>'
             '<li>Tie crossings with soft wire (baling wire, fence tie wire) twisted with pliers.</li>'
             '<li>Bend bars cold around a pipe or a post in a log; hooks at bar ends add anchorage. Do not heat rebar to bend it.</li>'
             '<li>Typical layouts: slab — #3 at 18 in or #4 at 24 in each way, or welded mesh/cattle panel, at mid-depth or slightly below; footing — 2–3 #4 continuous; lintel — 2 #4 at the bottom, 1½ in up; post — 4 #3 corner bars with wire ties every 8–12 in.</li></ul>')
    h.append('<h2 id="placing">6.4 Placing and compacting</h2>')
    h.append('<p>Place concrete as close to its final position as possible — don’t drag it with a rake or let it fall more than about 3–5 ft (stones separate). Fill in layers 6–12 in deep. Compact each layer by <b>rodding</b> (jabbing repeatedly with a rebar or pole), spading along form faces, and <b>tapping the outside of the forms</b> with a hammer until air bubbles stop rising and paste shows at the faces. Over-working brings water and fines to the surface — stop once it’s consolidated. Screed slabs level with a straight board sawed back and forth across the forms, float, then wait until the surface water has gone before final troweling. <b>Never trowel bleed water back into the surface</b> — it makes a weak, dusting skin.</p>')
    h.append('<h2 id="curing">6.5 Curing: the step everyone skips</h2>')
    h.append('<p>Cement only gains strength while it is damp and above freezing. Concrete allowed to dry out early may reach only half its potential strength (NRMCA CIP 11). <b>Keep new concrete continuously moist for at least 7 days</b> — 10–14 days for tanks, rings and anything that must be watertight, and longer in cool weather. Methods: cover with wet burlap, sacks or straw plus plastic sheeting; pond water on slabs behind a little dike of sand; bury small precast items in damp sand; sprinkle repeatedly. <b>Alternate wetting and drying is not curing</b> — keep it wet.</p>')
    h.append(table(["Condition", "What to do"], [
        ["<b>Cold</b> (3+ days averaging below 40 °F / 5 °C)", "Never pour on frozen ground or into forms with ice/snow. Heat the mix water (up to ~140 °F / 60 °C; add hot water to aggregate first, cement last) and keep aggregates unfrozen. Pour at midday. Insulate with straw 6+ in thick under tarps, blankets, or an enclosure warmed with a stove (vented — CO!). Protect from freezing until at least 500 psi (~2 days at 50 °F / 10 °C); keep above 50 °F for full curing; remove covers gradually. Use less water: wet concrete freezes worse. Lime work: stop building ~6 weeks before first frost (NRMCA CIP 27)"],
        ["<b>Hot / dry / windy</b>", "Pour early morning or evening; shade materials and the site; use cool water (well water, ice); wet the ground and forms first; have curing covers ready before you start; cover as soon as the surface sheen goes. Don’t sprinkle water on the surface to make finishing easier (NRMCA CIP 12)"],
        ["<b>Rain</b>", "Cover fresh work with plastic; a hard shower on fresh concrete washes out cement"]]))
    h.append('<h2 id="testing">6.6 Testing strength simply</h2>')
    h.append('<p>Make <b>test cubes</b> every time: fill 2–3 molds (a 4 in / 100 mm wooden cube mold, a cut-off plastic bottle, a tin can) from the same batch, rod them, and cure them right next to the real work. At 7 and 28 days, test them instead of your foundation:</p>')
    h.append(table(["Test", "Good sign", "Bad sign"], [
        ["Scratch with a steel nail or knife (7 days)", "Light scratch, no gouge, no dust", "Grooves easily, sand grains loosen"],
        ["Strike with a hammer", "Ringing sound, hammer bounces", "Dull thud, crumbles or dents"],
        ["Break a test cube with a sledge", "Breaks across the stones (stones themselves crack)", "Breaks around the stones, which pop out clean"],
        ["Soak a broken piece in water 24 h", "No change", "Softens, sand washes off (lime/pozzolan mixes take longer — test at 28–90 days)"],
        ["Load test (lever press)", "A 4 in (100 mm) cube must resist ~20 tons (18 t) to show 2,500 psi — beyond hand methods; compare cubes against a cube of known commercial concrete instead", "—"]]))
    return "\n".join(h)

def part7(D):
    h = ['<h1 class="part" id="p7"><small>Part 7</small>Projects</h1>']
    h.append('<h2 id="well">7.1 Well lining rings and well caps</h2>')
    h.append('<p>A hand-dug well needs a lining to stop collapse and to keep surface water out. The classic method (WEDC, Practical Action, many aid manuals) uses <b>precast concrete rings</b> sunk as a caisson: the bottom ring has a bevelled cutting edge; you dig out soil from inside and under it, and the ring sinks under its own weight while more rings are added on top. Below the water table, keep digging inside the rings so the shaft stays lined right down to the water-bearing layer.</p>')
    h.append(fig(D.well_ring_mold(), "<b>Figure 12. A collapsible mold for concrete well rings.</b> Rings can also be cast in place in the shaft, a section at a time, using the same mold. Make rings with holes or porous concrete (no-fines: cement + pea gravel only) for the bottom intake section.", "max-width:79%"))
    h.append('<div class="cols2"><div><h3>Making and sinking rings</h3><ul><li>Mix 1:2:3 (or 1:2:2 with ½ in gravel); reinforce with hoops of 6 mm bar or doubled fence wire every 6 in and 6–8 verticals.</li><li>Strip the inner mold after 12–24 h; cure under wet sacks for 7–14 days before handling. A 1 m (40 in) ring 75 mm thick and 0.5 m tall weighs about <b>300 kg (660 lb)</b>: lower with a tripod, chain hoist or windlass, never by hand.</li><li>Seal ring joints in the top 10 ft (3 m) with mortar so only filtered groundwater enters from below.</li><li>Keep everyone out of the shaft while lifting; ventilate deep shafts (lower a lit candle or use a fan — wells collect CO₂ and engine exhaust).</li></ul></div>'
             '<div><h3>Headwall, apron and cap</h3><ul><li>Extend the lining at least 1–2 ft (0.3–0.6 m) above ground as a headwall.</li><li>Pour a reinforced <b>apron</b> 4 in thick, extending ~3 ft (1 m) all around, sloping away to a drain channel, so spilled water and rain can’t run back down the outside of the shaft.</li><li><b>Well cap</b>: a reinforced slab 3–4 in thick (#3 bars or mesh at 6 in each way, 1 in up from the bottom) cast on a flat oiled board, with a sleeve for the pump pipe and a raised, lidded manhole with a downward-lapping lid. Seal it to the headwall with mortar.</li><li>Disinfect a new well before use (see the Water volume).</li></ul></div></div>')
    h.append('<h2 id="cistern">7.2 Cisterns and tanks</h2>')
    h.append('<p>Round tanks are far stronger than square ones (the walls work in simple hoop tension), so use cylinders where you can. Options: <b>ferrocement</b> (2–4 layers of chicken wire or welded mesh over a frame of rebar or high-tensile wire, plastered 1–2 in thick with a rich 1:2–1:3 mortar from both sides in one continuous session), <b>reinforced concrete</b> cast in forms, or brick/block with steel hoops and a thick cement render inside. A buried cistern needs walls designed for soil pressure when empty.</p>')
    h.append('<div class="formula"><span class="eq">Volume (US gal) = 5.875 × D² × H &nbsp; (feet)</span><span class="eq">Volume (litres) = 785 × D² × H &nbsp; (metres)</span>Example: 8 ft diameter × 6 ft deep = 2,256 gal; 2.5 m × 2 m = 9,800 L. 1 in of rain on 1,000 ft² of roof yields ~600 gal (1 mm on 1 m² = 1 L).</div>')
    h.append(check("Watertight tank checklist", ["Footing slab and walls cast or plastered in one continuous session where possible; if not, roughen and slurry joints with neat cement paste", "Inside: two or three coats of 1:2–1:3 render, each scratched before the next, finished with a cement-water slurry (“nil coat”)", "Cure 2–3 weeks under wet sacks before filling; then fill slowly", "Screened inlet with first-flush diverter, screened overflow, tight lid, outlet 4–6 in above the floor, and a drain/clean-out", "Flush the first fill to waste — new concrete makes water very alkaline for a few weeks", "Never use lime-only or gypsum plaster in a water tank; lime-pozzolan works if very thick and well cured"]))
    h.append('<h2 id="footing">7.3 Footings and foundations</h2>')
    h.append(fig(D.footing_form(), "<b>Figure 13. Forming a strip footing in a trench.</b> On firm soil the trench walls themselves can act as the form (“trench pour”); add side forms where the soil is loose or the footing rises above the trench.", "max-width:77%"))
    h.append('<p>The footing spreads the wall load over enough soil to stop it sinking, and must sit below the depth to which the ground freezes (frost heave lifts and cracks foundations). See Part 8 for sizing and frost depths by region. Pour footings in one go; leave vertical dowels or a keyway to lock the wall on. In soft ground, dig down to firm soil and refill with compacted gravel rather than building on fill.</p>')
    h.append('<h2 id="floor">7.4 Slab floors</h2>')
    h.append('<p>Strip topsoil, compact the subgrade, then lay 4–6 in (100–150 mm) of compacted gravel (a capillary break), a plastic vapor barrier (any heavy sheet, lapped 12 in), rigid insulation if available, and reinforcement on chairs. Pour 4 in (100 mm) of 1:2:4 (1:2:3 for heavy loads), screed, float and cure for 7+ days. Cut or tool <b>control joints</b> ¼ of the depth every 8–12 ft (2.5–3.5 m) so shrinkage cracks happen in straight lines. Slope 1–2% toward a drain in wet areas. Where cement is short: soil-cement or a lime-pozzolan floor on gravel, or a flagstone/brick floor laid on sand.</p>')
    h.append('<h2 id="blocks">7.5 Blocks and bricks</h2>')
    h.append('<p>See Part 4 for molds. Block production is a good use of cement because a dry, tamped block mix (1:6–1:8) stretches each bag much further than poured walls, and blocks can be made months ahead of the building season.</p>')
    h.append('<h2 id="cellar">7.6 Root cellar walls</h2>')
    h.append('<p>A root cellar wall is a retaining wall: soil pushes on it, harder when wet or frozen. Options: 8 in reinforced block with every core grouted and #4 vertical bars at 16–24 in, 8 in poured concrete, 18–24 in stone in lime mortar, or an <b>arched vault</b> (brick, stone or earthbags) which turns earth pressure into compression and needs little or no steel. Waterproof the outside face (bitumen, multiple coats of cement render, or heavy plastic), add a gravel drain and perforated pipe at the footing, and backfill with gravel against the wall. Provide a low intake and high exhaust vent. A dirt or gravel floor keeps humidity high (good for roots). Keep the roof slab or vault covered by at least 2–3 ft of earth for stable temperatures — see the Food volume for storage conditions.</p>')
    h.append('<h2 id="stove">7.7 Rocket stove and oven bases</h2>')
    h.append('<p>Ordinary concrete spalls and cracks above about 300 °C (570 °F) — water trapped in it turns to steam. So use concrete only for the <b>base</b> under a stove or bread oven, separated from the fire by an insulating layer: e.g., a 4 in reinforced slab on block piers, then 3–4 in of insulation (glass bottles laid in sand-clay, perlite-clay, or wood ash in clay), then a hearth of fire brick or dense clay. Build the fire chamber itself from fire brick, salvaged clay brick, or clay-sand (cob) mixes. For a castable refractory, mix 1 part fire clay : 2 parts grog/sand, or perlite and clay for insulating castables.</p>')
    h.append('<h2 id="posts">7.8 Fence posts</h2>')
    h.append('<p><b>Concrete posts</b> last generations where timber rots: cast 4 × 4 in (100 mm) or 5 × 5 in square, 6–7 ft long, tapered toward the top, in gang molds of lumber; reinforce with four #3 bars (or doubled high-tensile wire) ¾–1 in from each corner. Bore wire holes with oiled dowels left in the mold, or embed wire staples. 1:2:2 mix with ½ in gravel, well rodded; cure 2–4 weeks before setting. The Kansas Flint Hills used <b>solid limestone posts</b> split from a single ledge (“post rock”) — worth copying wherever thin-bedded limestone or sandstone outcrops. For <b>wooden posts</b>, set them in tamped gravel or crowned concrete collars that shed water; concrete poured around the bottom of a post traps water and rots it faster.</p>')
    return "\n".join(h)
